def asegurar_trozo_nombrado(pedazos, pieza, desde, hasta, texto, nombre):
    """Garantiza que lo que el problema nombra sobreviva al reparto del presupuesto.

    Devuelve una LISTA de pedazos. Si ya hay un pedazo de la MISMA pieza que contiene esos
    renglones (empieza antes o en el mismo sitio y termina despues o en el mismo sitio), no
    se agrega nada: a ese pedazo se le sube el puntaje a 99.0 y se le pone la marca con el
    nombre nombrado, y la lista devuelta trae los mismos pedazos que entraron, en el mismo
    orden. Si no hay ninguno que lo contenga, se AGREGA al principio un pedazo nuevo con esa
    pieza, esos renglones, ese texto, puntaje 99.0, la marca con el nombre, y su direccion
    escrita juntando la pieza, dos puntos, el renglon de inicio, un guion y el renglon final.
    Un pedazo de OTRA pieza nunca cuenta, aunque sus numeros de renglon coincidan. Nunca
    revienta: si le llega una lista vacia, nada, o algo que no es una lista, devuelve una
    lista que al menos trae el pedazo nombrado, y jamas lanza un error.
    """
    try:
        if not isinstance(pedazos, list):
            pedazos = []
        for t in pedazos:
            if not isinstance(t, dict):
                continue
            if t.get("pieza") != pieza:
                continue
            if t.get("desde") <= desde and t.get("hasta") >= hasta:
                t["puntaje"] = 99.0
                t["_completo"] = nombre
                return pedazos
        nuevo = {"pieza": pieza, "desde": desde, "hasta": hasta,
                 "direccion": "%s:%s-%s" % (pieza, desde, hasta),
                 "texto": texto, "puntaje": 99.0, "_completo": nombre}
        return [nuevo] + pedazos
    except Exception:
        return [{"pieza": pieza, "desde": desde, "hasta": hasta,
                 "direccion": "%s:%s-%s" % (pieza, desde, hasta),
                 "texto": texto, "puntaje": 99.0, "_completo": nombre}]


